# DK SBF.  Svendborg - Katterød (- Faaborg)
with detail = 2 {
    let sk = path("d2.dk.sbf");

    with railway = :first :pax :removed {
        with link = "line.dk.SBF" {
            track(sk[:sve.yf, :sve.yf + 11.5km]);
            line_label(:left:n, sk[:sve.yf + 11.5km], "SBF");
            track(sk[:sve.yf + 11.5km, :kat.ys]);
        }
    }
}


# DK SBS.  Skanderborg - Skjern
with detail = 2 {
    let ss = path("d2.dk.sbs");

    with railway = :first :pax {
        with link = "line.dk.SBS" {
            track(ss[:ska.ys, :ska.ys + 12.51km]);
            line_label(:right:sw, ss[:ska.ys + 12.5km] >> 0.5mt, "SBS");
            track(ss[:ska.ys + 12.49km, :sil.yl]);
        }

        with link = "point.dk.Silkeborg" {
            track(ss[:sil.yl, :sil.yh]);
            statdot(ss[:sil]);
            slabel(:top, ss[:sil] + (0dt, -0.3km) + (0dt, -1dt),
                "Silkeborg"
            );
        }

        with link = "line.dk.SBS" {
            track(ss[:sil.yh, :sil.yr]);
            track(ss[:sil.yr, :fun]);
        }

        with link = "point.dk.Funder" {
            statdot(:nopax, ss[:fun]);
            slabel(:right :nopax, ss[:fun] + (1.5dt, 2.5dt), "Funder");
        }

        with link = "line.dk.SBS" {
            track(ss[:fun, :fun.yb - 1mt]);
            with layer = -1 track(ss[:fun.yb - 1.1mt, :fun.yb + 1.5km]);
            track(ss[:fun.yb + 1.49km, :fun.yb + 14.01km]);
            line_label(:right:s, ss[:fun.yb + 14km] >> 0.5mt, "SBS");
            track(ss[:fun.yb + 13.99km, :her.ys]);
        }

        # point.dk.Herning  dk.HBV

        with link = "line.dk.SBS" {
            track(ss[:her.yh, :her.yh + 12.51km]);
            line_label(:right:se, ss[:her.yh + 12.5km] >> 0.5mt, "SBS");
            track(ss[:her.yh + 12.49km, :tro]);
        }

        with link = "point.dk.Troldhede" {
            track(ss[:tro, :tro.yk]);
            statdot(ss[:tro]);
            slabel(:left, ss[:tro] + (-1dt, -0.6dt), "Troldhede");
        }

        with link = "line.dk.SBS" {
            track(ss[:tro.yk, :tro.yk + 10.01km]);
            line_label(:right:s, ss[:tro.yk + 10km] >> 0.5mt,
                (-0.3dt, 0dt), "SBS"
            );
            track(ss[:tro.yk + 9.99km, :ske.ys]);
        }
    }
}


# DK SBT.  Sønderborg - Tønder
with detail = 2 {
    let st = path("d2.dk.sbt");

    with railway = :first :cat:ac25 :pax {
        with link = "point.dk.Sønderborg", railway = :station {
            statdot(st[:son]);
            slabel(:bottom, st[:son] + (0dt, 0.4km) + (0dt, 1dt),
                "Sønderborg"
            );
        }

        with link = "line.dk.SBT" {
            track(st[:son, :vso.ys]);
        }

        with link = "point.dk.Vester-Sottrup", railway = :station {
            track(st[:vso.ys, :vso]);
            statdot(:removed, st[:vso]);
            slabel(:right :removed, st[:vso] + (1dt, -0.8dt),
                "Vester Sottrup"
            );
        }

        with link = "line.dk.SBT" {
            track(st[:vso, :vso + 3.81km]);
            line_label(:right:s, st[:vso + 3.8km] >> 0.5mt, "SBT");
            track(st[:vso + 3.79km, :gra.ya]);
        }

        with link = "point.dk.Gråsten", railway = :station {
            track(st[:gra.ya, :gra]);
            statdot(st[:gra]);
            slabel(:left, st[:gra] + (-1.2dt, -0.5dt), "Gråsten");
        }

        with link = "line.dk.SBT" {
            track(st[:gra, :tor]);
        }

        with link = "point.dk.Tørsbøl", railway = :station {
            track(st[:tor, :tor.yp]);
            statdot(st[:tor]);
            slabel(:left, st[:tor] + (-1.5km, 0dt) + (-1.8dt, 0.3dt),
                "Tørsbøl"
            );
        }

        with link = "line.dk.SBT" {
            track(st[:tor.yp, :tor.yp + 6.01km]);
            line_label(:right:s, st[:tor.yp + 6km] >> 0.5mt, "SBT");
            track(
                    st[:tor.yp + 5.99km, :tin.xs - 0.5md]
                ..  st[:tin.ys, :tin.ys + 0.1dl] >> 0.5md << 0.5mt
            );
        }
    }

    # point.dk.Tinglev  dk.FPB

    with railway = :first :expax :suspended {
        with link = "line.dk.SBT" {
            track(st[:tin.yt, :tin.yt + 14.01km]);
            line_label(:right:s, st[:tin.yt + 14km] >> 0.5mt, "SBT");
            track(st[:tin.yt + 13.99km, :ton.yt]);
        }
    }
}


# DK SGG.  Skive - Glyngøre
with detail = 2 {
    let sg = path("d2.dk.sgg");
    let ski = path("d2.dk.sgg.ski");

    with railway = :first :pax :removed {
        with link = "point.dk.Skive", railway = :station {
            track(ski[:ski.ys, :ski]);
            statdot(ski[:ski]);
        }

        with link = "line.dk.SGG" {
            track(ski[:ski, :skn.yn]);
            track(sg[:ski.yg, :skn.yn]);
            track(sg[:skn.yn, :skn.ys]);
            track(sg[:skn.ys, :skn.ys + 11.01km]);
            line_label(:right:w, sg[:skn.ys + 11km] >> 0.5mt, "SGG");
            track(sg[:skn.ys + 10.99km, :gly]);
        }

        with link = "point.dk.Glyngøre", railway = :station {
            statdot(sg[:gly]);
            slabel(:ne, sg[:gly] + (1dt, 0.8dt), "Glyngøre");
        }
    }
}


