# DK SMM.  Sønderborg - Mommark Færge
with detail = 2 {
    let sm = path("d2.dk.smm");

    with railway = :first :pax :removed {
        with link = "line.dk.SMM" {
            track(sm[:son, :sob]);
        }

        with link = "point.dk.Sønderborg-By", railway = :station {
            statdot(sm[:sob]);
        }

        with link = "line.dk.SMM" {
            track(sm[:sob, :vol.yv]);
            track(sm[:vol.yv - 0.1dl, :vol.yo + 1dl]);
            track(sm[:vol.yo, :maj.yo]);
            track(sm[:maj.yo - 0.1dl, :nta.yt + 1dl]);
            track(sm[:nta.yt, :lmo]);
        }

        with link = "point.dk.Lille-Mommark", railway = :station {
            track(sm[:lmo, :lmo.ys]);
            statdot(sm[:lmo]);
            slabel(:left, sm[:lmo] + (-1.3dt, 2dt),
                vbox(:right:topbase, "Lille-", "Mommark   ")
            );
        }

        with link = "line.dk.SMM" {
            track(sm[:lmo.ys - 0.1dl, :lmo.ys + 2.41km]);
            line_label(:right:w, sm[:lmo.ys + 2.4km] >> 0.5mt, "SMM");
            track(sm[:lmo.ys + 2.39km, :mom]);
        }

        with link = "point.dk.Mommark-Færge", railway = :station {
            statdot(sm[:mom]);
            slabel(:right, sm[:mom] + (1.7dt, 0.9dt),
                "Mommark Færge"
            );
        }
    }
}


# DK SMS.  Svanemøllen - Slangerup
with detail = 2 {
    let ss = path("d2.dk.sms");

    with railway = :first :double :cat:dc15 :pax {
        with link = "line.dk.SMS" {
            track(
                    ss[:sva.yf - 0.1dl, :sva.yf] << 1md << 1ms
                ..  ss[:ryp, :ryp + 0.1dl]
            );
            track(ss[:ryp.yf, :emd.yl]);
            track(ss[:emd.yl, :emd.yl + 6.5km]);
            line_label(:left:ne, ss[:emd.yl + 6.5km], "SMS");
            track(ss[:emd.yl + 6.5km, :far.xs]);
            track(:single, ss[:far.xs, :far]);
        }

        with link = "point.dk.Farum" {
            statdot(ss[:far]);
            slabel(:right, ss[:far] + (1.5dt, 0.3dt), "Farum");
        }
    }

    with railway = :first :pax :removed {
        with link = "line.dk.SMS" {
            track(ss[:far, :far + 7km]);
            line_label(:left:n, ss[:far + 7km], "SMS");
            track(ss[:far + 7km, :sla.yh]);
            track(ss[:sla.yh, :sla]);
        }

        with link = "point.dk.Slangerup" {
            statdot(ss[:sla]);
            slabel(:left, ss[:sla] + (0.8dt, -1.5dt), "Slangerup");
        }
    }
}


